+import { afterEach, describe, expect, it, vi } from "vitest";
+import { retry } from "./retry";
+
+describe("retry", () => {
+  afterEach(() => vi.useRealTimers());
+
+  it("retries then rethrows the last error", async () => {
+    vi.useFakeTimers();
+    const fn = vi.fn().mockRejectedValueOnce(new Error("one")).mockRejectedValueOnce(new Error("two"));
+    const pending = retry(fn, { attempts: 2, baseMs: 10 });
+    const settled = pending.catch((e: Error) => e.message);
+    await vi.runAllTimersAsync();
+    expect(await settled).toBe("two");
+    expect(fn).toHaveBeenCalledTimes(2);
+  });
+});
